photos=[]
for n,line in enumerate(rows.splitlines(),1):
    slug,theme,uk,en,du,de,au,ae=line.split('|')
    supplied=uk + (' — 2026' if n in [6,15,16] else '')
    photos.append(dict(id='chronicle-'+slug,original_file=f'{n}.jpeg',catalog_title_uk=supplied,
        title=dict(uk=uk,en=en),caption=dict(uk=uk,en=en),caption_overlay=dict(uk=uk,en=en),
        description=dict(uk=du,en=de),alt=dict(uk=au,en=ae),theme=theme,category=theme,
        placements=['gallery',theme],home_featured=n in [1,3,5,6,17,18,19,25],
        contains_children=n not in [5,17,19,25,26],contains_aid_recipients=n in [17,25,26],
        publication_status='pending_approval',rights_confirmed=False,consents_confirmed=False,
        consent_reference=None,publication_authorization=None,captured_on=None,date_source=None,
        date_verification='Original Telegram event caption not supplied; do not infer from message time or camera watermark',
        verification_status='visually_verified_against_owner_file_catalog',
        visual_observation=dict(uk=au,en=ae),credit=dict(uk='Надано для сайту парафії',en='Provided for the parish website')))
catalog=dict(version=1,source='Owner file-to-scene catalogue supplied on 2026-11-02',photos=photos,
    missing=[dict(id='shared-heavy-building-work',title=dict(uk='Спільна праця біля храму',en='Working together beside the church'),
        status='missing',reason='Men carrying a heavy building element: no matching original on Desktop; no substitution.')])
dest=Path(__file__).resolve().parents[1]/'content/parish-photo-catalog.json'
assert not dest.exists(), 'Do not replace a prepared catalogue'
dest.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
